from lib import *
chapter(6,'maths','perimeter-and-area','Perimeter and Area',
 ('The garden fence','Ravi wants a fence around his rectangular garden and grass to cover the ground. The fence needs the distance around the garden. The grass needs the space inside. Two different measures, two different ideas: perimeter and area.'),
 [('Perimeter',['Perimeter is the total length of the boundary of a shape. Walk once around the shape and add every side.','For a rectangle with length l and breadth b the perimeter is 2 times l plus b.','For a square with side s the perimeter is 4 times s.','Perimeter is measured in units of length such as centimetres or metres.']),
  ('Area',['Area is the amount of surface a shape covers. We find it by counting unit squares that fit inside.','A unit square has side 1 unit. Area is measured in square units such as square centimetres.','A rectangle of length l and breadth b has area l times b. A square of side s has area s times s.','Shapes with the same perimeter can have different areas, and shapes with the same area can have different perimeters.']),
  ('Area of a triangle',['Two identical triangles fit together to make a parallelogram or a rectangle, so a triangle covers half of that rectangle.','The area of a triangle is half of base times height.','The height is measured at a right angle to the base, not along the slanted side.'])],
 [('A rectangle is 8 cm long and 5 cm wide. Find perimeter and area.',[('Perimeter is 2 times (8 plus 5), which is 26 cm.','Add length and breadth, then double.'),('Area is 8 times 5, which is 40 square cm.','Length times breadth.')]),
  ('A triangle has base 10 cm and height 6 cm. Find its area.',[('Area equals half of base times height.','Use the triangle rule.'),('Half of 10 times 6 is 30 square cm.','10 times 6 is 60, and half of 60 is 30.')])],
 ('Explain the difference between perimeter and area using a school playground.',['Perimeter is the boundary length, for the fence.','Area is the surface covered, for the grass.'],['Using centimetres for area.','Forgetting to halve for the triangle.']),
 ['Perimeter is the length around a shape.','Area is the surface covered, in square units.','Rectangle area is length times breadth.','Triangle area is half base times height.'],
 [num('a6-1',1,'What is the perimeter of a square of side 7 cm?',28,'4 times 7 is 28.',[(49,'49 is the area, not the perimeter.')],'cm'),
  num('a6-2',1,'What is the area of a rectangle 9 cm by 4 cm?',36,'9 times 4 is 36 square cm.',[(26,'26 is the perimeter.')],'square cm'),
  mcq('a6-3',1,'Area is measured in','square units',[('units of length','Length units measure boundaries.'),('degrees','Degrees measure angles.')],'We count unit squares.'),
  tf('a6-4',1,'A square and a rectangle with equal perimeters have equal area.',False,'Their areas differ; a 5 by 5 square has area 25, and a 7 by 3 rectangle has area 21.'),
  num('a6-5',2,'A triangle has base 12 cm and height 5 cm. Find its area.',30,'Half of 12 times 5 is 30 square cm.',[(60,'You forgot to halve.')],'square cm'),
  num('a6-6',2,'The perimeter of a rectangle is 30 cm and length is 9 cm. Find breadth.',6,'2 times (9 plus b) is 30, so 9 plus b is 15 and b is 6.',[(21,'Subtract 9 from 15, not 30.')],'cm'),
  mcq('a6-7',2,'Which needs perimeter?','Putting a border around a picture',[('Tiling a floor','Tiling covers surface: area.'),('Painting a wall','Painting covers surface: area.')],'The border runs along the edge.'),
  num('a6-8',2,'A square has area 64 square cm. What is its side?',8,'8 times 8 is 64.',[(16,'That is double the side.')],'cm'),
  num('a6-9',3,'A rectangular garden is 20 m by 15 m. A path needs fencing all round. How many metres of fence?',70,'2 times (20 plus 15) is 70.',[(300,'300 is the area.')],'m'),
  mcq('a6-10',3,'Two identical triangles together can make','a parallelogram',[('a circle','Triangles have straight sides.'),('a line','Triangles have area.')],'Put one triangle upside down next to the other.')],
 keep=['perimeter','area'])
